    /// <summary>
    /// Returns a strongly typed <see cref="DbConnection"/> instance.
    /// </summary>
    public override DbConnection CreateConnection() => new NpgsqlConnection();

    /// <summary>
    /// Returns a strongly typed <see cref="DbParameter"/> instance.
