// ReSharper disable once CheckNamespace
namespace NpgsqlTypes
{
    using global::System;
    using global::System.ComponentModel;
    using global::System.Diagnostics.CodeAnalysis;
    using global::System.Globalization;
    using global::System.Text;


/// <summary>
/// Represents a PostgreSQL range type.
/// </summary>
/// <typeparam name="T">The element type of the values in the range.</typeparam>
/// <remarks>
/// See: https://www.postgresql.org/docs/current/static/rangetypes.html
/// </remarks>
public readonly struct NpgsqlRange<T> : IEquatable<NpgsqlRange<T>>
{
    // -----------------------------------------------------------------------------------------------
    // Regarding bitwise flag checks via @roji:
    //
    // > Note that Flags.HasFlag() used to be very inefficient compared to simply doing the
    // > bit operation - this is why I've always avoided it. .NET Core 2.1 adds JIT intrinstics
    // > for this, making Enum.HasFlag() fast, but I honestly don't see the value over just doing
    // > a bitwise and operation, which would also be fast under .NET Core 2.0 and .NET Framework.
    //
    // See:
    //   - https://github.com/npgsql/npgsql/pull/1939#pullrequestreview-121308396
    //   - https://blogs.msdn.microsoft.com/dotnet/2018/04/18/performance-improvements-in-net-core-2-1
    // -----------------------------------------------------------------------------------------------

    /// <summary>
    /// Defined by PostgreSQL to represent an empty range.
    /// </summary>
    const string EmptyLiteral = "empty";

    /// <summary>
    /// Defined by PostgreSQL to represent an infinite lower bound.
    /// Some element types may have specific handling for this value distinct from a missing or null value.
    /// </summary>
    const string LowerInfinityLiteral = "-infinity";

    /// <summary>
    /// Defined by PostgreSQL to represent an infinite upper bound.
    /// Some element types may have specific handling for this value distinct from a missing or null value.
    /// </summary>
    const string UpperInfinityLiteral = "infinity";

    /// <summary>
    /// Defined by PostgreSQL to represent an null bound.
    /// Some element types may have specific handling for this value distinct from an infinite or missing value.
    /// </summary>
    const string NullLiteral = "null";

    /// <summary>
    /// Defined by PostgreSQL to represent a lower inclusive bound.
    /// </summary>
    const char LowerInclusiveBound = '[';

    /// <summary>
    /// Defined by PostgreSQL to represent a lower exclusive bound.
    /// </summary>
    const char LowerExclusiveBound = '(';

    /// <summary>
    /// Defined by PostgreSQL to represent an upper inclusive bound.
    /// </summary>
    const char UpperInclusiveBound = ']';

    /// <summary>
    /// Defined by PostgreSQL to represent an upper exclusive bound.
    /// </summary>
    const char UpperExclusiveBound = ')';

    /// <summary>
    /// Defined by PostgreSQL to separate the values for the upper and lower bounds.
    /// </summary>
    const char BoundSeparator = ',';

    /// <summary>
    /// The <see cref="TypeConverter"/> used by <see cref="Parse"/> to convert <see cref="string"/> bounds into <typeparamref name="T"/>.
    /// </summary>
    static TypeConverter? BoundConverter;

    /// <summary>
    /// True if <typeparamref name="T"/> implements <see cref="IEquatable{T}"/>; otherwise, false.
    /// </summary>
    static readonly bool HasEquatableBounds = typeof(IEquatable<T>).IsAssignableFrom(typeof(T));

    /// <summary>
    /// Represents the empty range. This field is read-only.
    /// </summary>
    public static readonly NpgsqlRange<T> Empty = new(default, default, RangeFlags.Empty);

    /// <summary>
    /// The lower bound of the range. Only valid when <see cref="LowerBoundInfinite"/> is false.
    /// </summary>
    [MaybeNull, AllowNull]
    public T LowerBound { get; }

    /// <summary>
    /// The upper bound of the range. Only valid when <see cref="UpperBoundInfinite"/> is false.
    /// </summary>
    [MaybeNull, AllowNull]
    public T UpperBound { get; }

    /// <summary>
    /// The characteristics of the boundaries.
    /// </summary>
    internal readonly RangeFlags Flags;

    /// <summary>
    /// True if the lower bound is part of the range (i.e. inclusive); otherwise, false.
    /// </summary>
    public bool LowerBoundIsInclusive => (Flags & RangeFlags.LowerBoundInclusive) != 0;

    /// <summary>
    /// True if the upper bound is part of the range (i.e. inclusive); otherwise, false.
    /// </summary>
    public bool UpperBoundIsInclusive => (Flags & RangeFlags.UpperBoundInclusive) != 0;

    /// <summary>
    /// True if the lower bound is indefinite (i.e. infinite or unbounded); otherwise, false.
    /// </summary>
    public bool LowerBoundInfinite => (Flags & RangeFlags.LowerBoundInfinite) != 0;

    /// <summary>
    /// True if the upper bound is indefinite (i.e. infinite or unbounded); otherwise, false.
    /// </summary>
    public bool UpperBoundInfinite => (Flags & RangeFlags.UpperBoundInfinite) != 0;

    /// <summary>
    /// True if the range is empty; otherwise, false.
    /// </summary>
    public bool IsEmpty => (Flags & RangeFlags.Empty) != 0;

    /// <summary>
    /// Constructs an <see cref="NpgsqlRange{T}"/> with inclusive and definite bounds.
    /// </summary>
    /// <param name="lowerBound">The lower bound of the range.</param>
    /// <param name="upperBound">The upper bound of the range.</param>
    public NpgsqlRange([AllowNull] T lowerBound, [AllowNull] T upperBound)
        : this(lowerBound, true, false, upperBound, true, false) { }

    /// <summary>
    /// Constructs an <see cref="NpgsqlRange{T}"/> with definite bounds.
    /// </summary>
    /// <param name="lowerBound">The lower bound of the range.</param>
    /// <param name="lowerBoundIsInclusive">True if the lower bound is is part of the range (i.e. inclusive); otherwise, false.</param>
    /// <param name="upperBound">The upper bound of the range.</param>
    /// <param name="upperBoundIsInclusive">True if the upper bound is part of the range (i.e. inclusive); otherwise, false.</param>
    public NpgsqlRange(
        [AllowNull] T lowerBound, bool lowerBoundIsInclusive,
        [AllowNull] T upperBound, bool upperBoundIsInclusive)
        : this(lowerBound, lowerBoundIsInclusive, false, upperBound, upperBoundIsInclusive, false) { }

    /// <summary>
    /// Constructs an <see cref="NpgsqlRange{T}"/>.
    /// </summary>
    /// <param name="lowerBound">The lower bound of the range.</param>
    /// <param name="lowerBoundIsInclusive">True if the lower bound is is part of the range (i.e. inclusive); otherwise, false.</param>
    /// <param name="lowerBoundInfinite">True if the lower bound is indefinite (i.e. infinite or unbounded); otherwise, false.</param>
    /// <param name="upperBound">The upper bound of the range.</param>
    /// <param name="upperBoundIsInclusive">True if the upper bound is part of the range (i.e. inclusive); otherwise, false.</param>
    /// <param name="upperBoundInfinite">True if the upper bound is indefinite (i.e. infinite or unbounded); otherwise, false.</param>
    public NpgsqlRange(
        [AllowNull] T lowerBound, bool lowerBoundIsInclusive, bool lowerBoundInfinite,
        [AllowNull] T upperBound, bool upperBoundIsInclusive, bool upperBoundInfinite)
        : this(
            lowerBound,
            upperBound,
            EvaluateBoundaryFlags(
                lowerBoundIsInclusive,
                upperBoundIsInclusive,
                lowerBoundInfinite,
                upperBoundInfinite)) { }

    /// <summary>
    /// Constructs an <see cref="NpgsqlRange{T}"/>.
    /// </summary>
    /// <param name="lowerBound">The lower bound of the range.</param>
    /// <param name="upperBound">The upper bound of the range.</param>
    /// <param name="flags">The characteristics of the range boundaries.</param>
    internal NpgsqlRange([AllowNull] T lowerBound, [AllowNull] T upperBound, RangeFlags flags) : this()
    {
        // TODO: We need to check if the bounds are implicitly empty. E.g. '(1,1)' or '(0,0]'.
        // See: https://github.com/npgsql/npgsql/issues/1943.

        LowerBound = (flags & RangeFlags.LowerBoundInfinite) != 0 ? default : lowerBound;
        UpperBound = (flags & RangeFlags.UpperBoundInfinite) != 0 ? default : upperBound;
        Flags = flags;

        if (IsEmptyRange(LowerBound, UpperBound, Flags))
        {
            LowerBound = default!;
            UpperBound = default!;
            Flags = RangeFlags.Empty;
        }
    }

    /// <summary>
    /// Attempts to determine if the range is malformed or implicitly empty.
    /// </summary>
    /// <param name="lowerBound">The lower bound of the range.</param>
    /// <param name="upperBound">The upper bound of the range.</param>
    /// <param name="flags">The characteristics of the range boundaries.</param>
    /// <returns>
    /// True if the range is implicitly empty; otherwise, false.
    /// </returns>
    static bool IsEmptyRange([AllowNull] T lowerBound, [AllowNull] T upperBound, RangeFlags flags)
    {
        // ---------------------------------------------------------------------------------
        // We only want to check for those conditions that are unambiguously erroneous:
        //   1. The bounds must not be default values (including null).
        //   2. The bounds must be definite (non-infinite).
        //   3. The bounds must be inclusive.
        //   4. The bounds must be considered equal.
        //
        // See:
        //  - https://github.com/npgsql/npgsql/pull/1939
        //  - https://github.com/npgsql/npgsql/issues/1943
        // ---------------------------------------------------------------------------------

        if ((flags & RangeFlags.Empty) == RangeFlags.Empty)
            return true;

        if ((flags & RangeFlags.Infinite) == RangeFlags.Infinite)
            return false;

        if ((flags & RangeFlags.Inclusive) == RangeFlags.Inclusive)
            return false;

        if (lowerBound is null || upperBound is null)
            return false;

        if (!HasEquatableBounds)
            return lowerBound?.Equals(upperBound) ?? false;

        var lower = (IEquatable<T>)lowerBound;
        var upper = (IEquatable<T>)upperBound;

        return !lower.Equals(default!) && !upper.Equals(default!) && lower.Equals(upperBound);
    }

    /// <summary>
    /// Evaluates the boundary flags.
    /// </summary>
    /// <param name="lowerBoundIsInclusive">True if the lower bound is is part of the range (i.e. inclusive); otherwise, false.</param>
    /// <param name="lowerBoundInfinite">True if the lower bound is indefinite (i.e. infinite or unbounded); otherwise, false.</param>
    /// <param name="upperBoundIsInclusive">True if the upper bound is part of the range (i.e. inclusive); otherwise, false.</param>
    /// <param name="upperBoundInfinite">True if the upper bound is indefinite (i.e. infinite or unbounded); otherwise, false.</param>
    /// <returns>
    /// The boundary characteristics.
    /// </returns>
    static RangeFlags EvaluateBoundaryFlags(bool lowerBoundIsInclusive, bool upperBoundIsInclusive, bool lowerBoundInfinite, bool upperBoundInfinite)
    {
        var result = RangeFlags.None;

        // This is the only place flags are calculated.
        if (lowerBoundIsInclusive)
            result |= RangeFlags.LowerBoundInclusive;
        if (upperBoundIsInclusive)
            result |= RangeFlags.UpperBoundInclusive;
        if (lowerBoundInfinite)
            result |= RangeFlags.LowerBoundInfinite;
        if (upperBoundInfinite)
            result |= RangeFlags.UpperBoundInfinite;

        // PostgreSQL automatically converts inclusive-infinities.
        // See: https://www.postgresql.org/docs/current/static/rangetypes.html#RANGETYPES-INFINITE
        if ((result & RangeFlags.LowerInclusiveInfinite) == RangeFlags.LowerInclusiveInfinite)
            result &= ~RangeFlags.LowerBoundInclusive;

        if ((result & RangeFlags.UpperInclusiveInfinite) == RangeFlags.UpperInclusiveInfinite)
            result &= ~RangeFlags.UpperBoundInclusive;

        return result;
    }

    /// <summary>
    /// Indicates whether the <see cref="NpgsqlRange{T}"/> on the left is equal to the <see cref="NpgsqlRange{T}"/> on the right.
    /// </summary>
    /// <param name="x">The <see cref="NpgsqlRange{T}"/> on the left.</param>
    /// <param name="y">The <see cref="NpgsqlRange{T}"/> on the right.</param>
    /// <returns>
    /// True if the <see cref="NpgsqlRange{T}"/> on the left is equal to the <see cref="NpgsqlRange{T}"/> on the right; otherwise, false.
    /// </returns>
    public static bool operator ==(NpgsqlRange<T> x, NpgsqlRange<T> y) => x.Equals(y);

    /// <summary>
    /// Indicates whether the <see cref="NpgsqlRange{T}"/> on the left is not equal to the <see cref="NpgsqlRange{T}"/> on the right.
    /// </summary>
    /// <param name="x">The <see cref="NpgsqlRange{T}"/> on the left.</param>
    /// <param name="y">The <see cref="NpgsqlRange{T}"/> on the right.</param>
    /// <returns>
    /// True if the <see cref="NpgsqlRange{T}"/> on the left is not equal to the <see cref="NpgsqlRange{T}"/> on the right; otherwise, false.
    /// </returns>
    public static bool operator !=(NpgsqlRange<T> x, NpgsqlRange<T> y) => !x.Equals(y);

    /// <inheritdoc />
    public override bool Equals(object? o) => o is NpgsqlRange<T> range && Equals(range);

    /// <inheritdoc />
    public bool Equals(NpgsqlRange<T> other)
    {
        if (Flags != other.Flags)
            return false;

        if (HasEquatableBounds)
        {
            var lowerEqual = LowerBound is null
                ? other.LowerBound is null
                : !(other.LowerBound is null) && ((IEquatable<T>)LowerBound).Equals(other.LowerBound);

            if (!lowerEqual)
                return false;

            return UpperBound is null
                ? other.UpperBound is null
                : !(other.UpperBound is null) && ((IEquatable<T>)UpperBound).Equals(other.UpperBound);
        }

        return
            (LowerBound?.Equals(other.LowerBound) ?? other.LowerBound is null) &&
            (UpperBound?.Equals(other.UpperBound) ?? other.UpperBound is null);
    }

    /// <inheritdoc />
    public override int GetHashCode()
        => unchecked((397 * (int)Flags) ^ (397 * (LowerBound?.GetHashCode() ?? 0)) ^ (397 * (UpperBound?.GetHashCode() ?? 0)));

    /// <inheritdoc />
    public override string ToString()
    {
        if (IsEmpty)
            return EmptyLiteral;

        var sb = new StringBuilder();

        sb.Append(LowerBoundIsInclusive ? LowerInclusiveBound : LowerExclusiveBound);

        if (!LowerBoundInfinite)
            sb.Append(LowerBound);

        sb.Append(BoundSeparator);

        if (!UpperBoundInfinite)
            sb.Append(UpperBound);

        sb.Append(UpperBoundIsInclusive ? UpperInclusiveBound : UpperExclusiveBound);

        return sb.ToString();
    }

    // TODO: rewrite this to use ReadOnlySpan<char> for the 4.1 release
    /// <summary>
    /// Parses the well-known text representation of a PostgreSQL range type into a <see cref="NpgsqlRange{T}"/>.
    /// </summary>
    /// <param name="value">A PosgreSQL range type in a well-known text format.</param>
    /// <returns>
    /// The <see cref="NpgsqlRange{T}"/> represented by the <paramref name="value"/>.
    /// </returns>
    /// <exception cref="FormatException">
    /// Malformed range literal.
    /// </exception>
    /// <exception cref="FormatException">
    /// Malformed range literal. Missing left parenthesis or bracket.
    /// </exception>
    /// <exception cref="FormatException">
    /// Malformed range literal. Missing right parenthesis or bracket.
    /// </exception>
    /// <exception cref="FormatException">
    /// Malformed range literal. Missing comma after lower bound.
    /// </exception>
    /// <remarks>
    /// See: https://www.postgresql.org/docs/current/static/rangetypes.html
    /// </remarks>
    [RequiresUnreferencedCode("Parse implementations for certain types of T may require members that have been trimmed.")]
    public static NpgsqlRange<T> Parse(string value)
    {
        if (value is null)
            throw new ArgumentNullException(nameof(value));

        value = value.Trim();

        if (value.Length < 3)
            throw new FormatException("Malformed range literal.");

        if (string.Equals(value, EmptyLiteral, StringComparison.OrdinalIgnoreCase))
            return Empty;

        var lowerInclusive = value[0] == LowerInclusiveBound;
        var lowerExclusive = value[0] == LowerExclusiveBound;

        if (!lowerInclusive && !lowerExclusive)
            throw new FormatException("Malformed range literal. Missing left parenthesis or bracket.");

        var upperInclusive = value[value.Length - 1] == UpperInclusiveBound;
        var upperExclusive = value[value.Length - 1] == UpperExclusiveBound;

        if (!upperInclusive && !upperExclusive)
            throw new FormatException("Malformed range literal. Missing right parenthesis or bracket.");

        var separator = value.IndexOf(BoundSeparator);

        if (separator == -1)
            throw new FormatException("Malformed range literal. Missing comma after lower bound.");

        if (separator != value.LastIndexOf(BoundSeparator))
            // TODO: this should be replaced to handle quoted commas.
            throw new NotSupportedException("Ranges with embedded commas are not currently supported.");

        // Skip the opening bracket and stop short of the separator.
        var lowerSegment = value.Substring(1, separator - 1).Trim();

        // Skip past the separator and stop short of the closing bracket.
        var upperSegment = value.Substring(separator + 1, value.Length - separator - 2).Trim();

        // TODO: infinity literals have special meaning to some types (e.g. daterange), we should consider a flag to track them.

        var lowerInfinite =
            lowerSegment.Length == 0 ||
            string.Equals(lowerSegment, string.Empty, StringComparison.OrdinalIgnoreCase) ||
            string.Equals(lowerSegment, NullLiteral, StringComparison.OrdinalIgnoreCase) ||
            string.Equals(lowerSegment, LowerInfinityLiteral, StringComparison.OrdinalIgnoreCase);

        var upperInfinite =
            upperSegment.Length == 0 ||
            string.Equals(upperSegment, string.Empty, StringComparison.OrdinalIgnoreCase) ||
            string.Equals(upperSegment, NullLiteral, StringComparison.OrdinalIgnoreCase) ||
            string.Equals(upperSegment, UpperInfinityLiteral, StringComparison.OrdinalIgnoreCase);

        BoundConverter ??= TypeDescriptor.GetConverter(typeof(T));
        var lower = lowerInfinite ? default : (T?)BoundConverter.ConvertFromString(lowerSegment);
        var upper = upperInfinite ? default : (T?)BoundConverter.ConvertFromString(upperSegment);

        return new NpgsqlRange<T>(lower, lowerInclusive, lowerInfinite, upper, upperInclusive, upperInfinite);
    }

    /// <summary>
    /// Represents a type converter for <see cref="NpgsqlRange{T}" />.
    /// </summary>
    [RequiresUnreferencedCode("ConvertFrom implementations for certain types of T may require members that have been trimmed.")]
    public class RangeTypeConverter : TypeConverter
    {
        /// <summary>
        /// Adds a <see cref="TypeConverterAttribute"/> to the closed form <see cref="NpgsqlRange{T}"/>.
        /// </summary>
        public static void Register() =>
            TypeDescriptor.AddAttributes(
                typeof(NpgsqlRange<T>),
                new TypeConverterAttribute(typeof(RangeTypeConverter)));

        /// <inheritdoc />
        public override bool CanConvertFrom(ITypeDescriptorContext? context, Type sourceType)
            => sourceType == typeof(string);

        /// <inheritdoc />
        public override bool CanConvertTo(ITypeDescriptorContext? context, Type? destinationType)
            => destinationType == typeof(string);

        /// <inheritdoc />
        public override object? ConvertFrom(ITypeDescriptorContext? context, CultureInfo? culture, object value)
            => value is string s ? Parse(s) : base.ConvertFrom(context, culture, value);

        /// <inheritdoc />
        public override object? ConvertTo(ITypeDescriptorContext? context, CultureInfo? culture, object? value, Type destinationType)
            => value is null ? string.Empty : value.ToString();
    }
}

/// <summary>
/// Represents characteristics of range type boundaries.
/// </summary>
/// <remarks>
/// See: https://www.postgresql.org/docs/current/static/rangetypes.html
/// </remarks>
[Flags]
enum RangeFlags : byte
{
    /// <summary>
    /// The default flag. The range is not empty and has boundaries that are definite and exclusive.
    /// </summary>
    None = 0,

    /// <summary>
    /// The range is empty. E.g. '(0,0)', 'empty'.
    /// </summary>
    Empty = 1,

    /// <summary>
    /// The lower bound is inclusive. E.g. '[0,5]', '[0,5)', '[0,)'.
    /// </summary>
    LowerBoundInclusive = 2,

    /// <summary>
    /// The upper bound is inclusive. E.g. '[0,5]', '(0,5]', '(,5]'.
    /// </summary>
    UpperBoundInclusive = 4,

    /// <summary>
    /// The lower bound is infinite or indefinite. E.g. '(null,5]', '(-infinity,5]', '(,5]'.
    /// </summary>
    LowerBoundInfinite = 8,

    /// <summary>
    /// The upper bound is infinite or indefinite. E.g. '[0,null)', '[0,infinity)', '[0,)'.
    /// </summary>
    UpperBoundInfinite = 16,

    /// <summary>
    /// Both the lower and upper bounds are inclusive.
    /// </summary>
    Inclusive = LowerBoundInclusive | UpperBoundInclusive,

    /// <summary>
    /// Both the lower and upper bounds are indefinite.
    /// </summary>
    Infinite = LowerBoundInfinite | UpperBoundInfinite,

    /// <summary>
    /// The lower bound is both inclusive and indefinite. This represents an error condition.
    /// </summary>
    LowerInclusiveInfinite = LowerBoundInclusive | LowerBoundInfinite,

    /// <summary>
    /// The upper bound is both inclusive and indefinite. This represents an error condition.
    /// </summary>
    UpperInclusiveInfinite = UpperBoundInclusive | UpperBoundInfinite
}

}
#pragma warning restore
#nullable restore

// src/Npgsql/NpgsqlTypes/NpgsqlTsQuery.cs

#pragma warning disable CA1034

// ReSharper disable once CheckNamespace
namespace NpgsqlTypes
{
    using global::System;
    using global::System.Collections.Generic;
    using global::System.Text;


/// <summary>
/// Represents a PostgreSQL tsquery. This is the base class for the
/// lexeme, not, or, and, and "followed by" nodes.
/// </summary>
public abstract class NpgsqlTsQuery : IEquatable<NpgsqlTsQuery>
{
    /// <summary>
    /// Node kind
    /// </summary>
    public NodeKind Kind { get; }

    /// <summary>
    /// NodeKind
    /// </summary>
    public enum NodeKind
    {
        /// <summary>
        /// Represents the empty tsquery. Should only be used at top level.
        /// </summary>
        Empty = -1,
        /// <summary>
        /// Lexeme
        /// </summary>
        Lexeme = 0,
        /// <summary>
        /// Not operator
        /// </summary>
        Not = 1,
        /// <summary>
        /// And operator
        /// </summary>
        And = 2,
        /// <summary>
        /// Or operator
        /// </summary>
        Or = 3,
        /// <summary>
        /// "Followed by" operator
        /// </summary>
        Phrase = 4
    }

    /// <summary>
    /// Constructs an <see cref="NpgsqlTsQuery"/>.
    /// </summary>
    /// <param name="kind"></param>
    protected NpgsqlTsQuery(NodeKind kind) => Kind = kind;

    /// <summary>
    /// Writes the tsquery in PostgreSQL's text format.
    /// </summary>
    public void Write(StringBuilder stringBuilder) => WriteCore(stringBuilder, true);

    internal abstract void WriteCore(StringBuilder sb, bool first = false);

    /// <summary>
    /// Writes the tsquery in PostgreSQL's text format.
    /// </summary>
    public override string ToString()
    {
        var sb = new StringBuilder();
        Write(sb);
        return sb.ToString();
    }

    /// <summary>
    /// Parses a tsquery in PostgreSQL's text format.
    /// </summary>
    /// <param name="value"></param>
    /// <returns></returns>
    [Obsolete("Client-side parsing of NpgsqlTsQuery is unreliable and cannot fully duplicate the PostgreSQL logic. Use PG functions instead (e.g. to_tsquery)")]
    public static NpgsqlTsQuery Parse(string value)
    {
        if (value == null)
            throw new ArgumentNullException(nameof(value));

        var valStack = new Stack<NpgsqlTsQuery>();
        var opStack = new Stack<NpgsqlTsQueryOperator>();

        var sb = new StringBuilder();
        var pos = 0;
        var expectingBinOp = false;

        short lastFollowedByOpDistance = -1;

        NextToken:
        if (pos >= value.Length)
            goto Finish;
        var ch = value[pos++];
        if (ch == '\'')
            goto WaitEndComplex;
        if ((ch == ')' || ch == '|' || ch == '&') && !expectingBinOp || (ch == '(' || ch == '!') && expectingBinOp)
            throw new FormatException("Syntax error in tsquery. Unexpected token.");

        if (ch == '<')
        {
            var endOfOperatorConsumed = false;
            var sbCurrentLength = sb.Length;

            while (pos < value.Length)
            {
                var c = value[pos++];
                if (c == '>')
                {
                    endOfOperatorConsumed = true;
                    break;
                }

                sb.Append(c);
            }

            if (sb.Length == sbCurrentLength || !endOfOperatorConsumed)
                throw new FormatException("Syntax error in tsquery. Malformed 'followed by' operator.");

            var followedByOpDistanceString = sb.ToString(sbCurrentLength, sb.Length - sbCurrentLength);
            if (followedByOpDistanceString == "-")
            {
                lastFollowedByOpDistance = 1;
            }
            else if (!short.TryParse(followedByOpDistanceString, out lastFollowedByOpDistance)
                     || lastFollowedByOpDistance < 0)
            {
                throw new FormatException("Syntax error in tsquery. Malformed distance in 'followed by' operator.");
            }

            sb.Length -= followedByOpDistanceString.Length;
        }

        if (ch == '(' || ch == '!' || ch == '&' || ch == '<')
        {
            opStack.Push(new NpgsqlTsQueryOperator(ch, lastFollowedByOpDistance));
            expectingBinOp = false;
            lastFollowedByOpDistance = 0;
            goto NextToken;
        }

        if (ch == '|')
        {
            if (opStack.Count > 0 && opStack.Peek() == '|')
            {
                if (valStack.Count < 2)
                    throw new FormatException("Syntax error in tsquery");
                var right = valStack.Pop();
                var left = valStack.Pop();
                valStack.Push(new NpgsqlTsQueryOr(left, right));
                // Implicit pop and repush |
            }
            else
                opStack.Push('|');
            expectingBinOp = false;
            goto NextToken;
        }

        if (ch == ')')
        {
            while (opStack.Count > 0 && opStack.Peek() != '(')
            {
                if (valStack.Count < 2 || opStack.Peek() == '!')
                    throw new FormatException("Syntax error in tsquery");

                var right = valStack.Pop();
                var left = valStack.Pop();

                var tsOp = opStack.Pop();
                valStack.Push((char)tsOp switch
                {
                    '&' => new NpgsqlTsQueryAnd(left, right),
                    '|' => new NpgsqlTsQueryOr(left, right),
                    '<' => new NpgsqlTsQueryFollowedBy(left, tsOp.FollowedByDistance, right),
                    _   => throw new FormatException("Syntax error in tsquery")
                });
            }
            if (opStack.Count == 0)
                throw new FormatException("Syntax error in tsquery: closing parenthesis without an opening parenthesis");
            opStack.Pop();
            goto PushedVal;
        }

        if (ch == ':')
            throw new FormatException("Unexpected : while parsing tsquery");

        if (char.IsWhiteSpace(ch))
            goto NextToken;

        pos--;
        if (expectingBinOp)
            throw new FormatException("Unexpected lexeme while parsing tsquery");
        // Proceed to WaitEnd

        WaitEnd:
        if (pos >= value.Length || char.IsWhiteSpace(ch = value[pos]) || ch == '!' || ch == '&' || ch == '|' || ch == '(' || ch == ')')
        {
            valStack.Push(new NpgsqlTsQueryLexeme(sb.ToString()));
            goto PushedVal;
        }
        pos++;
        if (ch == ':')
        {
            valStack.Push(new NpgsqlTsQueryLexeme(sb.ToString()));
            sb.Clear();
            goto InWeightInfo;
        }
        if (ch == '\\')
        {
            if (pos >= value.Length)
                throw new FormatException(@"Unexpected \ in end of value");
            ch = value[pos++];
        }
        sb.Append(ch);
        goto WaitEnd;

        WaitEndComplex:
        if (pos >= value.Length)
            throw new FormatException("Missing terminating ' in string literal");
        ch = value[pos++];
        if (ch == '\'')
        {
            if (pos < value.Length && value[pos] == '\'')
            {
                ch = '\'';
                pos++;
            }
            else
            {
                valStack.Push(new NpgsqlTsQueryLexeme(sb.ToString()));
                if (pos < value.Length && value[pos] == ':')
                {
                    pos++;
                    goto InWeightInfo;
                }
                goto PushedVal;
            }
        }
        if (ch == '\\')
        {
            if (pos >= value.Length)
                throw new FormatException(@"Unexpected \ in end of value");
            ch = value[pos++];
        }
        sb.Append(ch);
        goto WaitEndComplex;


        InWeightInfo:
        if (pos >= value.Length)
            goto Finish;
        ch = value[pos];
        switch (ch)
        {
        case '*':
            ((NpgsqlTsQueryLexeme)valStack.Peek()).IsPrefixSearch = true;
            break;
        case 'a' or 'A':
            ((NpgsqlTsQueryLexeme)valStack.Peek()).Weights |= NpgsqlTsQueryLexeme.Weight.A;
            break;
        case 'b' or 'B':
            ((NpgsqlTsQueryLexeme)valStack.Peek()).Weights |= NpgsqlTsQueryLexeme.Weight.B;
            break;
        case 'c' or 'C':
            ((NpgsqlTsQueryLexeme)valStack.Peek()).Weights |= NpgsqlTsQueryLexeme.Weight.C;
            break;
        case 'd' or 'D':
            ((NpgsqlTsQueryLexeme)valStack.Peek()).Weights |= NpgsqlTsQueryLexeme.Weight.D;
            break;
        default:
            goto PushedVal;
        }

        pos++;
        goto InWeightInfo;

        PushedVal:
        sb.Clear();
        var processTightBindingOperator = true;
        while (opStack.Count > 0 && processTightBindingOperator)
        {
            var tsOp = opStack.Peek();
            switch (tsOp)
            {
            case '&':
                if (valStack.Count < 2)
                    throw new FormatException("Syntax error in tsquery");
                var andRight = valStack.Pop();
                var andLeft = valStack.Pop();
                valStack.Push(new NpgsqlTsQueryAnd(andLeft, andRight));
                opStack.Pop();
                break;

            case '!':
                if (valStack.Count == 0)
                    throw new FormatException("Syntax error in tsquery");
                valStack.Push(new NpgsqlTsQueryNot(valStack.Pop()));
                opStack.Pop();
                break;

            case '<':
                if (valStack.Count < 2)
                    throw new FormatException("Syntax error in tsquery");
                var followedByRight = valStack.Pop();
                var followedByLeft = valStack.Pop();
                valStack.Push(
                    new NpgsqlTsQueryFollowedBy(
                        followedByLeft,
                        tsOp.FollowedByDistance,
                        followedByRight));
                opStack.Pop();
                break;

            default:
                processTightBindingOperator = false;
                break;
            }
        }
        expectingBinOp = true;
        goto NextToken;

        Finish:
        while (opStack.Count > 0)
        {
            if (valStack.Count < 2)
                throw new FormatException("Syntax error in tsquery");

            var right = valStack.Pop();
            var left = valStack.Pop();

            var tsOp = opStack.Pop();
            var query = (char)tsOp switch
            {
                '&' => (NpgsqlTsQuery)new NpgsqlTsQueryAnd(left, right),
                '|' => new NpgsqlTsQueryOr(left, right),
                '<' => new NpgsqlTsQueryFollowedBy(left, tsOp.FollowedByDistance, right),
                _   => throw new FormatException("Syntax error in tsquery")
            };
            valStack.Push(query);
        }
        if (valStack.Count != 1)
            throw new FormatException("Syntax error in tsquery");
        return valStack.Pop();
    }

    /// <inheritdoc/>
    public override int GetHashCode()
        => throw new NotSupportedException("Must be overridden");

    /// <inheritdoc/>
    public override bool Equals(object? obj)
        => obj is NpgsqlTsQuery query && query.Equals(this);

    /// <summary>
    /// Returns a value indicating whether this instance and a specified <see cref="NpgsqlTsQuery"/> object represent the same value.
    /// </summary>
    /// <param name="other">An object to compare to this instance.</param>
    /// <returns><see langword="true"/> if g is equal to this instance; otherwise, <see langword="false"/>.</returns>
    public abstract bool Equals(NpgsqlTsQuery? other);

    /// <summary>
    /// Indicates whether the values of two specified <see cref="NpgsqlTsQuery"/> objects are equal.
    /// </summary>
    /// <param name="left">The first object to compare.</param>
    /// <param name="right">The second object to compare.</param>
    /// <returns><see langword="true"/> if <paramref name="left"/> and <paramref name="right"/> are equal; otherwise, <see langword="false"/>.</returns>
    public static bool operator ==(NpgsqlTsQuery? left, NpgsqlTsQuery? right)
        => left is null ? right is null : left.Equals(right);

    /// <summary>
    /// Indicates whether the values of two specified <see cref="NpgsqlTsQuery"/> objects are not equal.
    /// </summary>
    /// <param name="left">The first object to compare.</param>
    /// <param name="right">The second object to compare.</param>
    /// <returns><see langword="true"/> if <paramref name="left"/> and <paramref name="right"/> are not equal; otherwise, <see langword="false"/>.</returns>
    public static bool operator !=(NpgsqlTsQuery? left, NpgsqlTsQuery? right)
        => left is null ? right is not null : !left.Equals(right);
}

readonly struct NpgsqlTsQueryOperator
{
    public readonly char Char;
    public readonly short FollowedByDistance;

    public NpgsqlTsQueryOperator(char character, short followedByDistance)
    {
        Char = character;
        FollowedByDistance = followedByDistance;
    }

    public static implicit operator NpgsqlTsQueryOperator(char c) => new(c, 0);
    public static implicit operator char(NpgsqlTsQueryOperator o) => o.Char;
}

/// <summary>
/// TsQuery Lexeme node.
/// </summary>
public sealed class NpgsqlTsQueryLexeme : NpgsqlTsQuery
{
    string _text;

    /// <summary>
    /// Lexeme text.
    /// </summary>
    public string Text
    {
        get => _text;
        set
        {
            if (string.IsNullOrEmpty(value))
                throw new ArgumentException("Text is null or empty string", nameof(value));

            _text = value;
        }
    }

    Weight _weights;

    /// <summary>
    /// Weights is a bitmask of the Weight enum.
    /// </summary>
    public Weight Weights
    {
        get => _weights;
        set
        {
            if (((byte)value >> 4) != 0)
                throw new ArgumentOutOfRangeException(nameof(value), "Illegal weights");

            _weights = value;
        }
    }

    /// <summary>
    /// Prefix search.
    /// </summary>
    public bool IsPrefixSearch { get; set; }

    /// <summary>
    /// Creates a tsquery lexeme with only lexeme text.
    /// </summary>
    /// <param name="text">Lexeme text.</param>
    public NpgsqlTsQueryLexeme(string text) : this(text, Weight.None, false) { }

    /// <summary>
    /// Creates a tsquery lexeme with lexeme text and weights.
    /// </summary>
    /// <param name="text">Lexeme text.</param>
    /// <param name="weights">Bitmask of enum Weight.</param>
    public NpgsqlTsQueryLexeme(string text, Weight weights) : this(text, weights, false) { }

    /// <summary>
    /// Creates a tsquery lexeme with lexeme text, weights and prefix search flag.
    /// </summary>
    /// <param name="text">Lexeme text.</param>
    /// <param name="weights">Bitmask of enum Weight.</param>
    /// <param name="isPrefixSearch">Is prefix search?</param>
    public NpgsqlTsQueryLexeme(string text, Weight weights, bool isPrefixSearch)
        : base(NodeKind.Lexeme)
    {
        _text = text;
        Weights = weights;
        IsPrefixSearch = isPrefixSearch;
    }

    /// <summary>
    /// Weight enum, can be OR'ed together.
    /// </summary>
#pragma warning disable CA1714
    [Flags]
    public enum Weight
#pragma warning restore CA1714
    {
        /// <summary>
        /// None
        /// </summary>
        None = 0,
        /// <summary>
        /// D
        /// </summary>
        D = 1,
        /// <summary>
        /// C
        /// </summary>
        C = 2,
        /// <summary>
        /// B
        /// </summary>
        B = 4,
        /// <summary>
        /// A
        /// </summary>
        A = 8
    }

    internal override void WriteCore(StringBuilder sb, bool first = false)
    {
        sb.Append('\'').Append(Text.Replace(@"\", @"\\").Replace("'", "''")).Append('\'');
        if (IsPrefixSearch || Weights != Weight.None)
            sb.Append(':');
        if (IsPrefixSearch)
            sb.Append('*');
        if ((Weights & Weight.A) != Weight.None)
            sb.Append('A');
        if ((Weights & Weight.B) != Weight.None)
            sb.Append('B');
        if ((Weights & Weight.C) != Weight.None)
            sb.Append('C');
        if ((Weights & Weight.D) != Weight.None)
            sb.Append('D');
    }

    /// <inheritdoc/>
    public override bool Equals(NpgsqlTsQuery? other)
        => other is NpgsqlTsQueryLexeme lexeme &&
           lexeme.Text == Text &&
           lexeme.Weights == Weights &&
           lexeme.IsPrefixSearch == IsPrefixSearch;

    /// <inheritdoc/>
    public override int GetHashCode()
        => HashCode.Combine(Text, Weights, IsPrefixSearch);
}

/// <summary>
/// TsQuery Not node.
/// </summary>
public sealed class NpgsqlTsQueryNot : NpgsqlTsQuery
{
    /// <summary>
    /// Child node
    /// </summary>
    public NpgsqlTsQuery Child { get; set; }

    /// <summary>
    /// Creates a not operator, with a given child node.
    /// </summary>
    /// <param name="child"></param>
    public NpgsqlTsQueryNot(NpgsqlTsQuery child)
        : base(NodeKind.Not)
    {
        Child = child;
    }

    internal override void WriteCore(StringBuilder sb, bool first = false)
    {
        sb.Append('!');
        if (Child == null)
        {
            sb.Append("''");
        }
        else
        {
            if (Child.Kind != NodeKind.Lexeme)
                sb.Append("( ");
            Child.WriteCore(sb, true);
            if (Child.Kind != NodeKind.Lexeme)
                sb.Append(" )");
        }
    }

    /// <inheritdoc/>
    public override bool Equals(NpgsqlTsQuery? other)
        => other is NpgsqlTsQueryNot not && not.Child == Child;

    /// <inheritdoc/>
    public override int GetHashCode()
        => Child?.GetHashCode() ?? 0;
}

/// <summary>
/// Base class for TsQuery binary operators (&amp; and |).
/// </summary>
public abstract class NpgsqlTsQueryBinOp : NpgsqlTsQuery
{
    /// <summary>
    /// Left child
    /// </summary>
    public NpgsqlTsQuery Left { get; set; }

    /// <summary>
    /// Right child
    /// </summary>
    public NpgsqlTsQuery Right { get; set; }

    /// <summary>
    /// Constructs a <see cref="NpgsqlTsQueryBinOp"/>.
    /// </summary>
    protected NpgsqlTsQueryBinOp(NodeKind kind, NpgsqlTsQuery left, NpgsqlTsQuery right)
        : base(kind)
    {
        Left = left;
        Right = right;
    }
}

/// <summary>
/// TsQuery And node.
/// </summary>
public sealed class NpgsqlTsQueryAnd : NpgsqlTsQueryBinOp
{
    /// <summary>
    /// Creates an and operator, with two given child nodes.
    /// </summary>
    /// <param name="left"></param>
    /// <param name="right"></param>
    public NpgsqlTsQueryAnd(NpgsqlTsQuery left, NpgsqlTsQuery right)
        : base(NodeKind.And, left, right) {}

    internal override void WriteCore(StringBuilder sb, bool first = false)
    {
        Left.WriteCore(sb);
        sb.Append(" & ");
        Right.WriteCore(sb);
    }

    /// <inheritdoc/>
    public override bool Equals(NpgsqlTsQuery? other)
        => other is NpgsqlTsQueryAnd and && and.Left == Left && and.Right == Right;

    /// <inheritdoc/>
    public override int GetHashCode()
        => HashCode.Combine(Left, Right);
}

/// <summary>
/// TsQuery Or Node.
/// </summary>
public sealed class NpgsqlTsQueryOr : NpgsqlTsQueryBinOp
{
    /// <summary>
    /// Creates an or operator, with two given child nodes.
    /// </summary>
    /// <param name="left"></param>
    /// <param name="right"></param>
    public NpgsqlTsQueryOr(NpgsqlTsQuery left, NpgsqlTsQuery right)
        : base(NodeKind.Or, left, right) {}

    internal override void WriteCore(StringBuilder sb, bool first = false)
    {
        // TODO: Figure out the nullability strategy here
        if (!first)
            sb.Append("( ");

        Left.WriteCore(sb);
        sb.Append(" | ");
        Right.WriteCore(sb);

        if (!first)
            sb.Append(" )");
    }

    /// <inheritdoc/>
    public override bool Equals(NpgsqlTsQuery? other)
        => other is NpgsqlTsQueryOr or && or.Left == Left && or.Right == Right;

    /// <inheritdoc/>
    public override int GetHashCode()
        => HashCode.Combine(Left, Right);
}

/// <summary>
/// TsQuery "Followed by" Node.
/// </summary>
public sealed class NpgsqlTsQueryFollowedBy : NpgsqlTsQueryBinOp
{
    /// <summary>
    /// The distance between the 2 nodes, in lexemes.
    /// </summary>
    public short Distance { get; set; }

    /// <summary>
    /// Creates a "followed by" operator, specifying 2 child nodes and the
    /// distance between them in lexemes.
    /// </summary>
    /// <param name="left"></param>
    /// <param name="distance"></param>
    /// <param name="right"></param>
    public NpgsqlTsQueryFollowedBy(
        NpgsqlTsQuery left,
        short distance,
        NpgsqlTsQuery right)
        : base(NodeKind.Phrase, left, right)
    {
        if (distance < 0)
            throw new ArgumentOutOfRangeException(nameof(distance));

        Distance = distance;
    }

    internal override void WriteCore(StringBuilder sb, bool first = false)
    {
        // TODO: Figure out the nullability strategy here
        if (!first)
            sb.Append("( ");

        Left.WriteCore(sb);

        sb.Append(" <");
        if (Distance == 1) sb.Append("-");
        else sb.Append(Distance);
        sb.Append("> ");

        Right.WriteCore(sb);

        if (!first)
            sb.Append(" )");
    }

    /// <inheritdoc/>
    public override bool Equals(NpgsqlTsQuery? other)
        => other is NpgsqlTsQueryFollowedBy followedBy &&
           followedBy.Left == Left &&
           followedBy.Right == Right &&
           followedBy.Distance == Distance;

    /// <inheritdoc/>
    public override int GetHashCode()
        => HashCode.Combine(Left, Right, Distance);
}

/// <summary>
/// Represents an empty tsquery. Shold only be used as top node.
/// </summary>
public sealed class NpgsqlTsQueryEmpty : NpgsqlTsQuery
{
    /// <summary>
    /// Creates a tsquery that represents an empty query. Should not be used as child node.
    /// </summary>
    public NpgsqlTsQueryEmpty() : base(NodeKind.Empty) {}

    internal override void WriteCore(StringBuilder sb, bool first = false) { }

    /// <inheritdoc/>
    public override bool Equals(NpgsqlTsQuery? other)
        => other is NpgsqlTsQueryEmpty;

    /// <inheritdoc/>
    public override int GetHashCode()
        => Kind.GetHashCode();
}

}
